import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"Getting Started","description":"Your 5-step quickstart guide to generating AI videos with Sanjeev AI.","frontmatter":{"title":"Getting Started","description":"Your 5-step quickstart guide to generating AI videos with Sanjeev AI."},"headers":[],"relativePath":"user_guides/getting-started.md","filePath":"user_guides/getting-started.md"}'),i={name:"user_guides/getting-started.md"};function s(n,e,l,c,d,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Welcome to Sanjeev AI! This guide will walk you through the core 5-step process to go from a raw script to a published YouTube video.</p><h2 id="step-1-create-a-project-import-your-script" tabindex="-1">Step 1: Create a Project &amp; Import Your Script <a class="header-anchor" href="#step-1-create-a-project-import-your-script" aria-label="Permalink to &quot;Step 1: Create a Project &amp; Import Your Script&quot;">​</a></h2><ol><li>On the <strong>Dashboard</strong>, click <strong>New Project</strong>.</li><li>Give it a name and click <strong>Create Workspace</strong>.</li><li>Inside the project, click <strong>New Script</strong> and paste your text into the modal.</li><li>Our AI Parser will automatically break your script into scenes and detect characters.</li></ol><h2 id="step-2-assign-cast-voices" tabindex="-1">Step 2: Assign Cast &amp; Voices <a class="header-anchor" href="#step-2-assign-cast-voices" aria-label="Permalink to &quot;Step 2: Assign Cast &amp; Voices&quot;">​</a></h2><ol><li>In the <strong>Unified Studio</strong>, click the <strong>Cast &amp; Locations</strong> button in the toolbar.</li><li>Ensure every character has a physical description (for visual generation) and an assigned AI Voice Model (for audio).</li></ol><h2 id="step-3-run-the-ai-director" tabindex="-1">Step 3: Run the AI Director <a class="header-anchor" href="#step-3-run-the-ai-director" aria-label="Permalink to &quot;Step 3: Run the AI Director&quot;">​</a></h2><ol><li>Click <strong>Automate</strong> to open the Workflow Orchestrator.</li><li>Select <strong>Guided Mode</strong>.</li><li>The AI Director will analyze your scenes and automatically write detailed visual prompts for the image generator.</li></ol><h2 id="step-4-generate-media" tabindex="-1">Step 4: Generate Media <a class="header-anchor" href="#step-4-generate-media" aria-label="Permalink to &quot;Step 4: Generate Media&quot;">​</a></h2><p>Review the scenes. For each scene, you can:</p><ul><li><strong>Generate Audio</strong>: Synthesizes the character&#39;s voice.</li><li><strong>Generate Visual</strong>: Uses Imagen or Veo to create the scene&#39;s imagery based on the Director&#39;s prompt.</li></ul><h2 id="step-5-export-publish" tabindex="-1">Step 5: Export &amp; Publish <a class="header-anchor" href="#step-5-export-publish" aria-label="Permalink to &quot;Step 5: Export &amp; Publish&quot;">​</a></h2><ol><li>Once all media is generated and approved, click <strong>Render Final Video</strong>.</li><li>Choose <strong>Cloud Render</strong> to stitch the MP4 together.</li><li>Open the <strong>Publish Modal</strong> to let the AI write your YouTube metadata, and click <strong>Publish</strong> to send it directly to your channel!</li></ol>',13)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
